import { assertAudioTrackIdentity, assertCompositionIdentity, assertVisualTrackIdentity, sealComposition } from "@hypit/composition";
import { assertCanvas } from "@hypit/spatial";
import { assertTimelineIdentity } from "@hypit/timeline";
function assertNonEmpty(value, label) {
    if (!value.trim())
        throw new Error(`${label} must not be empty.`);
}
function trackKey(track) {
    return `${track.kind}\u0000${track.id}`;
}
function filmProgramContent(value) {
    return {
        id: value.id,
        clearColor: value.clearColor,
    };
}
function filmTrackSetContent(value) {
    return {
        tracks: [...value.tracks]
            .map((track) => structuredClone(track))
            .sort((left, right) => trackKey(left).localeCompare(trackKey(right))),
    };
}
export function sealFilmProgram(value) {
    return filmProgramContent(value);
}
export function assertFilmProgramIdentity(program) {
    assertNonEmpty(program.id, "FilmProgram id");
    if (!/^#[0-9a-f]{6}(?:[0-9a-f]{2})?$/iu.test(program.clearColor)) {
        throw new Error("FilmProgram clear color is invalid.");
    }
}
function sealFilmTrackSet(value) {
    return filmTrackSetContent(value);
}
export function assertFilmTrackSetIdentity(set) {
    const ids = new Set();
    for (const track of set.tracks) {
        if (ids.has(track.id))
            throw new Error(`FilmTrackSet contains duplicate Track id ${track.id}.`);
        ids.add(track.id);
        if (track.kind === "visual")
            assertVisualTrackIdentity(track);
        else
            assertAudioTrackIdentity(track);
    }
}
export function createFilmTrackSet() {
    return sealFilmTrackSet({
        tracks: [],
    });
}
function appendTrack(set, timeline, track) {
    assertFilmTrackSetIdentity(set);
    assertTimelineIdentity(timeline);
    if (track.kind === "visual")
        assertVisualTrackIdentity(track, timeline);
    else
        assertAudioTrackIdentity(track, timeline);
    if (set.tracks.some((existing) => existing.id === track.id)) {
        throw new Error(`FilmTrackSet already contains Track id ${track.id}.`);
    }
    return sealFilmTrackSet({
        tracks: [...set.tracks, track],
    });
}
export function appendFilmVisualTrack(set, timeline, track) {
    return appendTrack(set, timeline, track);
}
export function appendFilmAudioTrack(set, timeline, track) {
    return appendTrack(set, timeline, track);
}
export function compileFilmComposition(program, canvas, timeline, set) {
    assertFilmProgramIdentity(program);
    assertCanvas(canvas);
    assertTimelineIdentity(timeline);
    assertFilmTrackSetIdentity(set);
    const composition = sealComposition({
        id: program.id,
        canvas: {
            width: canvas.widthPx,
            height: canvas.heightPx,
            clearColor: program.clearColor,
        },
        tracks: set.tracks,
    });
    assertCompositionIdentity(composition, timeline);
    return composition;
}
